import os
import shutil
import uuid

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    os.makedirs(BACKUP_DIR, exist_ok=True)
    while True:
        candidate = os.path.join(BACKUP_DIR, f"backup_{uuid.uuid4().hex}")
        if not os.path.exists(candidate):
            return candidate


def task_func(directory):
    """
    Create a backup of the given directory and then clean its contents.

    Returns:
        tuple: (backup_directory_path, errors_list)
    """
    errors = []
    backup_dir = get_unique_backup_dir()

    if not os.path.isdir(directory):
        errors.append(f"source is not a directory: {directory}")
        return backup_dir, errors

    try:
        os.makedirs(BACKUP_DIR, exist_ok=True)
        shutil.copytree(directory, backup_dir)
    except Exception as exc:
        errors.append(f"backup failed: {exc}")
        if os.path.exists(backup_dir):
            try:
                shutil.rmtree(backup_dir)
            except Exception as cleanup_exc:
                errors.append(
                    f"failed to remove partial backup '{backup_dir}': {cleanup_exc}"
                )
        return backup_dir, errors

    try:
        for entry in os.listdir(directory):
            path = os.path.join(directory, entry)
            try:
                if os.path.isdir(path) and not os.path.islink(path):
                    shutil.rmtree(path)
                else:
                    os.unlink(path)
            except Exception as exc:
                errors.append(f"cleanup failed for '{path}': {exc}")
    except Exception as exc:
        errors.append(f"failed to list source directory for cleanup: {exc}")

    return backup_dir, errors
